import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        final long MOD = 1000000007;
        while (scanner.hasNextLong()) {
            long p = scanner.nextLong();
            long k = scanner.nextLong();
            long length_of_power;
            if (k == 0) {
                length_of_power = p - 1;
            } else if (k == 1) {
                length_of_power = p;
            } else {
                length_of_power = -1;
            }
            long result_value = 1;
            if (length_of_power == -1) {
                long count = 1;
                long v = k;
                while (v != 1) {
                    v = (v * k) % p;
                    count++;
                }
                length_of_power = p / count;
            }
            for (long i = 0; i < length_of_power; i++) {
                result_value = (result_value * p) % MOD;
            }
            System.out.println(result_value);
        }
        scanner.close();
    }
}
